50	// runResolveCLI writes config to a temp file, spawns the helper test binary
51	// with "resolve <config>" and feeds the request on stdin.
52	func runResolveCLI(t *testing.T, config, request string) resolveResult {
53		t.Helper()
54	
55		dir := t.TempDir()
56		configPath := filepath.Join(dir, "config.json")
57		if err := os.WriteFile(configPath, []byte(config), 0o600); err != nil {
58			t.Fatalf("write config: %v", err)
59		}
60	
61		cmd := exec.Command(os.Args[0], "-test.run=^TestHelperProcess$", "--", "resolve", configPath)
62		cmd.Env = append(os.Environ(), helperEnv+"=1")
63		cmd.Stdin = strings.NewReader(request)
64		var stdout, stderr bytes.Buffer
65		cmd.Stdout = &stdout
66		cmd.Stderr = &stderr
67	
68		err := cmd.Run()
69		exitCode := 0
70		if err != nil {
71			var exitErr *exec.ExitError
72			if errors.As(err, &exitErr) {
73				exitCode = exitErr.ExitCode()
74			} else {
75				t.Fatalf("run resolve helper: %v", err)
76			}
77		}
78		return resolveResult{stdout: stdout.Bytes(), stderr: stderr.Bytes(), exitCode: exitCode}
