1409				}
1410				var fail struct {
1411					Code   string `json:"code"`
1412					Reason string `json:"reason"`
1413				}
1414				decodeOneJSON(t, res.stderr, "stderr", &fail)
1415				if fail.Code != "invalid_request" {
1416					t.Fatalf("code = %q, want invalid_request", fail.Code)
1417				}
1418				for _, want := range []string{"target", tc.want} {
1419					if !strings.Contains(fail.Reason, want) {
1420						t.Errorf("reason = %q, want substring %q", fail.Reason, want)
1421					}
1422				}
1423			})
1424		}
1425	
1426		// Percent-encoded control bytes stay data: the request resolves and the
1427		// escapes reach upstreamURL byte for byte.
1428		encoded := assertResolveSuccess(t, runResolveCLI(t, cliSuccessConfig,
1429			`{"method":"GET","target":"/api/orders%20next?note=%0A%09"}`))
1430		if encoded.RouteID != "api" {
1431			t.Errorf("routeId = %q, want api (encoded space keeps the segment under /api)", encoded.RouteID)
1432		}
1433		if want := "http://api.internal/v1/orders%20next?note=%0A%09"; encoded.UpstreamURL != want {
1434			t.Errorf("upstreamURL = %q, want %q", encoded.UpstreamURL, want)
1435		}
1436	
1437		// Config validation still precedes request parsing: a bad config paired
1438		// with a newline target yields invalid_config, and stdout stays empty.
1439		badConfig := `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"ftp://h"}]}`
1440		res := runResolveCLI(t, badConfig, `{"method":"GET","target":"/a\n"}`)
1441		if res.exitCode == 0 || len(res.stdout) != 0 {
1442			t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
1443		}
1444		var fail struct {
1445			Code string `json:"code"`
1446		}
1447		decodeOneJSON(t, res.stderr, "stderr", &fail)
1448		if fail.Code != "invalid_config" {
