			config := `{
			  "routes": [
			    {"id": "hit", "methods": ["*"], "pathPrefix": "/",
			     "upstream": "http://hit.internal"},
			    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin",
			     "upstream": "http://admin.internal",
			     "queryTransforms": [
