// TestResolveCLIUnbracketedHostExtraColon drives the at-most-one-colon rule
// at the command boundary: an unbracketed host part with two or more colons
// — a name:name:port spelling that parses as neither a domain nor an IPv6
// literal, or a malformed IPv6-shaped spelling — rejects the whole config up
// front even when the request only hits the valid first route and even
// though the document is legal JSON. Failure keeps the usual contract:
// non-zero exit, completely empty stdout and one JSON invalid_config error
// on stderr whose reason names the route position, its id and the upstream
// field and says the unbracketed host part carries an extra colon.
func TestResolveCLIUnbracketedHostExtraColon(t *testing.T) {
	cases := []struct {
		name     string
		upstream string
	}{
		{"headline name name port with a base path", "http://api:internal:8080/base"},
		{"name part and a numeric end", "http://name:part:80"},
		{"malformed ipv6 shaped spelling", "http://2001:db8:::1/base"},
		{"name spelling under https without a base path", "https://svc:name:8443"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			config := `{
			  "routes": [
			    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
			    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin", "upstream": "` + tc.upstream + `"}
			  ]
			}`
			// The request hits the valid first route only.
			res := runResolveCLI(t, config, cliSuccessRequest)

			if res.exitCode == 0 {
				t.Fatalf("exit code = 0, want non-zero")
			}
			if len(res.stdout) != 0 {
				t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
			}
			var fail struct {
				Code   string `json:"code"`
				Reason string `json:"reason"`
			}
			decodeOneJSON(t, res.stderr, "stderr", &fail)
			if fail.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", fail.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "more than one colon"} {
				if !strings.Contains(fail.Reason, want) {
					t.Errorf("reason = %q, want substring %q", fail.Reason, want)
				}
			}
			if strings.Contains(fail.Reason, "not valid JSON") {
				t.Errorf("an extra-colon host is a content error, not a JSON syntax failure: %q", fail.Reason)
			}
			if strings.Contains(fail.Reason, "invalid port") {
				t.Errorf("the reason must name the extra colon, not a generic url.Parse port error: %q", fail.Reason)
			}
		})
	}

	// Colons that belong to userinfo or the base path stay legal end to end:
	// the headline example from the rule's scope resolves byte for byte.
	config := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api",
	  "upstream":"http://user:pa:ss@api.internal:8080/base/a:b"}]}`
	success := assertResolveSuccess(t, runResolveCLI(t, config,
		`{"method":"GET","target":"/api/items?z=1"}`))
	if success.RouteID != "api" {
		t.Errorf("routeId = %q, want api", success.RouteID)
	}
	if want := "http://user:pa:ss@api.internal:8080/base/a:b/items?z=1"; success.UpstreamURL != want {
		t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, want)
	}
}

// TestResolveCLIUpstreamMissingHost drives the non-empty-host rule at the
// command boundary: url.Parse accepts "http://:8080/base" with an empty
// hostname, so without the explicit check the route resolves to an upstream
// URL without a host. Every port-only, userinfo-only or empty authority
// rejects the whole config while it is read — even on a route the request
// never hits — with non-zero exit, completely empty stdout and one JSON
// invalid_config error on stderr whose reason names the route position, its
// id and the upstream field and says the upstream is missing a host. It must
// neither be reported as broken config JSON nor mislabeled an
// IPv6-bracket problem, and an invalid request still loses to the config
// error.
func TestResolveCLIUpstreamMissingHost(t *testing.T) {
	cases := []struct {
		name     string
		upstream string
	}{
		{"bare port under a base path", "http://:8080/base"},
		{"bare port without a base path", "https://:8443"},
		{"empty port under a base path", "http://:/base"},
		{"encoded userinfo before a bare port", "https://user:p%40ss@:8443/v1"},
		{"plain userinfo before an empty port", "http://user:pass@:/base"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			config := `{
			  "routes": [
			    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
			    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin", "upstream": "` + tc.upstream + `"}
			  ]
			}`
			// The request hits the valid first route only.
			res := runResolveCLI(t, config, cliSuccessRequest)

			if res.exitCode == 0 {
				t.Fatalf("exit code = 0, want non-zero")
			}
			if len(res.stdout) != 0 {
				t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
			}
			var fail struct {
				Code   string `json:"code"`
				Reason string `json:"reason"`
			}
			decodeOneJSON(t, res.stderr, "stderr", &fail)
			if fail.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", fail.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "missing a host"} {
				if !strings.Contains(fail.Reason, want) {
					t.Errorf("reason = %q, want substring %q", fail.Reason, want)
				}
			}
			for _, forbidden := range []string{"not valid JSON", "bracket"} {
				if strings.Contains(fail.Reason, forbidden) {
					t.Errorf("reason = %q must not say %q: an empty host is an address-content error",
						fail.Reason, forbidden)
				}
			}
		})
	}

	// Config validation precedes request parsing, so an invalid request still
	// yields the config error, not invalid_request.
	badConfig := `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/x","upstream":"https://user:p%40ss@:8443/v1"}]}`
	res := runResolveCLI(t, badConfig, `{not json`)
	if res.exitCode == 0 || len(res.stdout) != 0 {
		t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
	}
	var fail struct {
		Code string `json:"code"`
	}
	decodeOneJSON(t, res.stderr, "stderr", &fail)
	if fail.Code != "invalid_config" {
		t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
	}

	// A host that is present but simply followed by an empty port keeps its
	// existing behavior end to end, base path and query joined by the usual
	// rules.
	config := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api",
	  "upstream":"http://api.internal:/base"}]}`
	success := assertResolveSuccess(t, runResolveCLI(t, config,
		`{"method":"GET","target":"/api/items?z=1"}`))
	if success.RouteID != "api" {
		t.Errorf("routeId = %q, want api", success.RouteID)
	}
	if want := "http://api.internal:/base/items?z=1"; success.UpstreamURL != want {
		t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, want)
	}
}

func TestResolveCLIBracketedHostMustBeIPv6(t *testing.T) {
	// Brackets may enclose only a legal IPv6 literal. A name or an IPv4
	// address in brackets on a route the request never reaches still rejects
	// the whole config up front: non-zero exit, empty stdout and one JSON
	// error on stderr whose reason names the route position, its id and the
	// upstream field, and says the bracketed host is not a legal IPv6 address
	// — it must not be reported as broken config JSON.
	cases := []struct {
		name     string
		upstream string
	}{
		{"name in brackets", "http://[not-an-ip]/v1"},
		{"bare ipv4 in brackets", "http://[127.0.0.1]:8080/v1"},
		{"empty brackets", "http://[]/v1"},
		{"malformed ipv6", "http://[2001:db8:::1]/v1"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			config := `{
			  "routes": [
			    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
			    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin", "upstream": "` + tc.upstream + `"}
			  ]
			}`
			// The request hits the valid first route only.
			res := runResolveCLI(t, config, cliSuccessRequest)

			if res.exitCode == 0 {
				t.Fatalf("exit code = 0, want non-zero")
			}
			if len(res.stdout) != 0 {
				t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
			}
			var fail struct {
				Code   string `json:"code"`
				Reason string `json:"reason"`
			}
			decodeOneJSON(t, res.stderr, "stderr", &fail)
			if fail.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", fail.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "IPv6"} {
				if !strings.Contains(fail.Reason, want) {
					t.Errorf("reason = %q, want substring %q", fail.Reason, want)
				}
			}
			if strings.Contains(fail.Reason, "not valid JSON") {
				t.Errorf("a bad bracketed host is a content error, not a JSON syntax failure: %q", fail.Reason)
			}
		})
	}

	// A malformed request paired with a bad bracketed-host config still
	// reports invalid_config: config validation precedes request parsing.
	badConfig := `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/x","upstream":"http://[not-an-ip]/v1"}]}`
	res := runResolveCLI(t, badConfig, `{not json`)
	if res.exitCode == 0 || len(res.stdout) != 0 {
		t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
	}
	var fail struct {
		Code string `json:"code"`
	}
	decodeOneJSON(t, res.stderr, "stderr", &fail)
	if fail.Code != "invalid_config" {
		t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
	}
}

// TestResolveCLIUnbracketedIPv6Host drives the missing-bracket rule at the
// command boundary: a full, compressed or IPv4-tail IPv6 literal written
// without square brackets — with a digit suffix, a zone or userinfo too —
// rejects the whole config up front, even on a route the request never
// hits. Non-zero exit, completely empty stdout and one JSON invalid_config
// error on stderr whose reason names the route position, its id and the
// upstream field and says the IPv6 host is missing brackets; it must not be
// reported as broken config JSON, and an invalid request still loses to the
// config error.
func TestResolveCLIUnbracketedIPv6Host(t *testing.T) {
	cases := []struct {
		name     string
		upstream string
	}{
		{"compressed address under base path", "http://2001:db8::1/base"},
		{"compressed address with trailing digits", "http://::1:8080/base"},
		{"embedded ipv4 tail", "http://::ffff:192.0.2.1/base"},
		{"full form", "http://2001:0db8:0000:0000:0000:0000:0000:0001/base"},
		{"address and trailing digits, no base path", "http://fe80::1:8080"},
		{"percent encoded zone without brackets", "http://fe80::1%25eth0/base"},
		{"encoded userinfo and a port-like suffix", "https://user:p%40ss@2001:db8::1:8443/base"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			config := `{
			  "routes": [
			    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
			    {"id": "admin", "methods": ["GET"], "pathPrefix": "/admin", "upstream": "` + tc.upstream + `"}
			  ]
			}`
			// The request hits the valid first route only.
			res := runResolveCLI(t, config, cliSuccessRequest)

			if res.exitCode == 0 {
				t.Fatalf("exit code = 0, want non-zero")
