	// payload must be exactly one JSON object.
	var extra struct{}
	dec := json.NewDecoder(bytes.NewReader(res.stderr))
	if err := dec.Decode(&struct{}{}); err != nil {
		t.Fatalf("stderr is not JSON: %v", err)
