// startResolve starts the helper without waiting, so the test can observe
// whether the child is still blocked on stdin. The returned cleanup waits
// for (or kills) the process and collects its output.
func startResolve(t *testing.T, config string, stdin io.Reader) (*exec.Cmd, func() resolveResult) {
	t.Helper()

	dir := t.TempDir()
	configPath := filepath.Join(dir, "config.json")
	if err := os.WriteFile(configPath, []byte(config), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}

	pr, pw := io.Pipe()
	cmd := exec.Command(os.Args[0], "-test.run=^TestHelperProcess$", "--", "resolve", configPath)
	cmd.Env = append(os.Environ(), helperEnv+"=1")
	cmd.Stdin = stdin
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Start(); err != nil {
		t.Fatalf("start resolve helper: %v", err)
	}

	done := make(chan resolveResult, 1)
	go func() {
		err := cmd.Wait()
		exitCode := 0
		if err != nil {
			var exitErr *exec.ExitError
			if errors.As(err, &exitErr) {
				exitCode = exitErr.ExitCode()
			}
		}
		done <- resolveResult{stdout: stdout.Bytes(), stderr: stderr.Bytes(), exitCode: exitCode}
	}()

	cleanup := func() resolveResult {
		select {
		case res := <-done:
			return res
		case <-time.After(5 * time.Second):
			_ = cmd.Process.Kill()
			res := <-done
			t.Fatalf("resolve did not exit; stdout=%q stderr=%q", res.stdout, res.stderr)
			return res
		}
	}
	return cmd, cleanup
}

