// caller writes the request to the returned writer and MUST close it before
// calling cleanup (the child may finish without reading stdin, in which case
// exec.Cmd.Wait stays blocked on its stdin-copy goroutine until this end
// closes). The returned cleanup waits for the child and collects its output.
func startResolve(t *testing.T, config string) (*exec.Cmd, *io.PipeWriter, func() resolveResult) {
	t.Helper()

	dir := t.TempDir()
	configPath := filepath.Join(dir, "config.json")
	if err := os.WriteFile(configPath, []byte(config), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
